content.text:
+.cr-file { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
+#cr-create { margin-top: 8px; }
+.cr-preview-wrap { margin-top: 12px; }
+.cr-preview-wrap canvas {
+  width: 100%;
+  background: rgba(0, 0, 0, 0.35);
+  border: 1px solid var(--hair);
+  border-radius: 12px;
+  image-rendering: pixelated;
+}
+.cr-preview-wrap .cap { margin-top: 4px; }
+
+/* icon picker */
+.ic-cur { display: inline-flex; align-items: center; gap: 8px; }
+.ic-cur .aicon { width: 16px; height: 16px; }
+.ic-emoji { font-size: 14px; }
+.icon-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 7px; margin-top: 8px; }
+.icon-cell {
+  height: 40px; display: flex; align-items: center; justify-content: center;
+  background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.07);
+  border-radius: 10px;
+  cursor: pointer; font-size: 17px;
+  transition: all 0.14s ease;
+}
+.icon-cell .aicon { width: 20px; height: 20px; }
+.icon-cell:hover { background: rgba(255,255,255,0.08); }
+.icon-cell.sel { border-color: var(--amber); background: rgba(232, 176, 106, 0.12); }
+.icon-cell.ic-sym svg { width: 18px; height: 18px; }
+.ic-sym svg { width: 15px; height: 15px; }
+
+/* ---- misc leftovers (kept for logic safety) -------------------------------- */
+.help-btn {
+  width: 20px; height: 20px; border-radius: 50%; flex: 0 0 auto; align-self: center;
+  background: transparent; border: 1.5px solid rgba(255,255,255,0.3);
+  color: var(--sec); cursor: pointer; font-size: 11px; font-weight: 600;
+  display: inline-flex; align-items: center; justify-content: center;
+  padding: 0; line-height: 1; margin-right: 2px;
+}
+.help-btn:hover { border-color: var(--txt); color: var(--txt); }
+.agent-row {
+  display: flex; align-items: center; gap: 8px;
+  padding: 9px 14px; border-top: 1px solid var(--hair);
+}
+.agent-row .meta { flex: 1; min-width: 0; }
+.agent-row:first-child { border-top: 0; }
+.agent-row .meta .name { font-size: 13px; }
+.agent-row .meta .note { font-size: 11px; color: var(--sec); max-width: 330px; }
+.agent-row .meta .note.warn { color: var(--orange); }
+.agent-row button {
+  background: rgba(255,255,255,0.06); color: var(--txt);
+  border: 0; border-radius: 7px; padding: 4px 13px; cursor: pointer; font-size: 12px;
+}
+.agent-row button:hover { background: rgba(255,255,255,0.12); }
+.agent-row button.remove { color: var(--sec); }
+.lp-btn {
+  background: var(--amber-grad); color: var(--amber-deep); border: 0;
+  border-radius: 999px;
+  padding: 6px 17px; font-size: 12.5px; font-weight: 650; cursor: pointer;
+  display: inline-flex; align-items: center; gap: 6px; flex: 0 0 auto;
+}
+.lp-btn:hover { filter: brightness(1.06); }
+.lp-btn .ui-ic svg { width: 13px; height: 13px; }
+.preview-btns { display: flex; gap: 7px; }
+.preview-btns button {
+  background: rgba(255,255,255,0.06); color: var(--txt); border: 0;
+  border-radius: 8px; padding: 5px 13px; font-size: 12px; cursor: pointer;
+}
+.preview-btns button:hover { background: var(--amber); color: var(--amber-deep); }
+.sess-row { display: flex; align-items: center; gap: 9px; padding: 8px 14px; border-top: 1px solid var(--hair); }
+.sess-row:first-child { border-top: 0; }
+.sess-dot { width: 8px; height: 8px; border-radius: 50%; background: #8A8578; flex: 0 0 auto; }
+.sess-row[data-state="working"] .sess-dot { background: var(--amber); }
+.sess-row[data-state="waiting"] .sess-dot { background: var(--orange); }
+.sess-row[data-state="done"] .sess-dot { background: var(--green); }
+.sess-icon { width: 15px; height: 15px; object-fit: contain; flex: 0 0 auto; }
+.sess-meta { display: flex; flex-direction: column; min-width: 0; flex: 1; }
+.sess-name { font-weight: 600; font-size: 13px; }
+.sess-sub { font-size: 11px; color: var(--sec); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
+.sess-time { font-size: 11px; color: var(--sec); font-variant-numeric: tabular-nums; }
+.sess-x { background: none; border: 0; color: var(--sec); cursor: pointer; font-size: 11px; padding: 2px 4px; visibility: hidden; }
+.sess-row:hover .sess-x { visibility: visible; }
+.sess-x:hover { color: var(--red); }
+.idle-playlist-wrap { margin-top: 14px; padding-top: 12px; border-top: 1px solid rgba(255,255,255,0.12); }
+.idle-title { font-size: 13px; font-weight: 600; margin-bottom: 4px; }
+.idle-toolbar { display: flex; gap: 12px; margin: 8px 0 10px; }
+.idle-toolbar button { font-size: 12px; color: var(--amber); background: transparent; border: none; padding: 0; cursor: pointer; }
+.idle-toolbar button:hover { text-decoration: underline; }
+.idle-mode-row, .idle-interval-row { display: flex; align-items: center; gap: 10px; margin-top: 8px; }
+.idle-interval-row input[type="number"] {
+  width: 60px; background: rgba(0,0,0,0.28); color: var(--txt);
+  border: 1px solid var(--hair); border-radius: 8px; padding: 5px 8px; font-size: 12.5px; outline: none;
+}
+.idle-interval-row input[type="number"]:focus { border-color: rgba(232,176,106,0.5); }
+.roam-pause-fields, .quick-bubble-duration { display: inline-flex; align-items: center; gap: 6px; }
+.roam-pause-fields input[type="number"], .quick-bubble-duration input[type="number"] {
+  width: 64px; background: rgba(0,0,0,0.28); color: var(--txt);
+  border: 1px solid var(--hair); border-radius: 8px; padding: 5px 7px; font-size: 12.5px; outline: none;
+}
+.roam-pause-fields input[type="number"]:focus, .quick-bubble-duration input[type="number"]:focus { border-color: rgba(232,176,106,0.5); }
+.code-input { font-family: var(--font-mono); text-transform: uppercase; letter-spacing: .2em; width: 120px; text-align: center; }
+.history-list { display: flex; flex-direction: column; gap: 2px; max-height: 420px; overflow: auto; }
+.hist-day { font-size: 10px; text-transform: uppercase; letter-spacing: .04em; opacity: .5; margin: 10px 0 4px; }
+.hist-row { display: flex; align-items: baseline; gap: 8px; padding: 5px 8px; border-radius: 8px; }
+.hist-row:hover { background: rgba(127,127,127,.10); }
+.hist-agent { font-size: 10px; text-transform: uppercase; opacity: .6; min-width: 54px; }
+.hist-title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
+.hist-meta { font-size: 11px; white-space: nowrap; }
+
+@media (max-width: 1100px) {
+  .pet-panel { flex-basis: 240px; padding-inline: 14px; }
+  .pages { padding: 18px 20px 28px; }
+  .page.sel { width: 100%; }
+}
+
+@media (max-width: 820px) {
+  .pet-panel { flex-basis: 220px; }
+  .tabbar.dock { gap: 4px; padding-inline: 10px; }
+  .dock .tab { padding: 8px 10px; }
+  .row { align-items: flex-start; }
+  .row .seg { flex-wrap: wrap; justify-content: flex-end; }
+  .slider-wrap { min-width: 0; max-width: none; }
+  .size-presets { margin-left: 0; }
+  .library-actions { flex-direction: column; align-items: flex-start; }
+  .two-btns { flex-wrap: wrap; }
+  .section-head { align-items: center; }
+}
+
+/* ============================================================================
+   2. PET OVERLAY (transparent window: pet sprite + bubble)
+============================================================================ */
+html, body.overlay {
+  background: transparent !important;
+  overflow: hidden;
+  width: 100%;
+  height: 100%;
+  font-family: var(--font-ui);
+  cursor: default;
+}
+body.overlay, body.overlay * {
+  user-select: none;
+  -webkit-user-select: none;
+}
+
+#pet-root {
+  position: absolute;
+  bottom: 0;
+  left: 50%;
+  transform: translateX(-50%);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 5px;
+}
+#pet {
+  image-rendering: pixelated;
+  cursor: grab;
+}
+
+/* speech bubble: ember glass */
+.bubble {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  gap: 3px;
+  max-width: 270px;
+  padding: 9px 15px;
+  border-radius: 16px;
+  background: var(--bubble-bg, rgba(24, 18, 12, 0.92));
+  color: var(--bubble-fg, #F6F0E4);
+  border: 1px solid var(--bubble-border, rgba(232, 176, 106, 0.22));
+  font-size: var(--bubble-font-size, 12px);
+  font-family: var(--bubble-font-family, var(--font-ui));
+  font-weight: 500;
+  line-height: 1.45;
+  text-align: center;
+  margin-bottom: 6px;
+  box-shadow:
+    0 10px 30px rgba(0, 0, 0, 0.45),
+    0 2px 8px rgba(0, 0, 0, 0.28),
+    inset 0 1px 0 rgba(255, 255, 255, 0.06);
+  transition: opacity 0.2s ease, transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
+}
+.bubble[hidden] { display: none; }
+.bubble::after {
+  content: "";
+  position: absolute;
+  left: 50%;
+  bottom: -6px;
+  transform: translateX(-50%);
+  border: 7px solid transparent;
+  border-top: 7px solid var(--bubble-bg, rgba(24, 18, 12, 0.92));
+  border-bottom: 0;
+}
+.bubble .brow.focusable { cursor: pointer; border-radius: 8px; transition: background 0.12s; }
+.bubble .brow.focusable:hover { background: rgba(255, 255, 255, 0.10); }
+.bubble .approval { display: inline-flex; gap: 5px; margin-left: 6px; }
+.bubble .approval button {
+  font: inherit; font-size: 10px; font-weight: 600;
+  border: none; border-radius: 999px; padding: 1px 9px; cursor: pointer;
+}
+.bubble .approval .ap-allow { background: rgba(143, 216, 168, 0.16); color: var(--green); }
+.bubble .approval .ap-deny { background: rgba(229, 122, 110, 0.18); color: var(--red); }
+.bubble .brow {
+  display: flex;
+  align-items: center;
+  gap: 5px;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+  max-width: 330px;
+}
+.bubble .single-line {
+  transition: opacity 0.18s ease;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+  max-width: 330px;
+}
+.bubble .single-line.fade { opacity: 0; }
+.bubble.capsule { border-radius: 999px; }
+
+.bubble .aicon { width: 14px; height: 14px; flex: 0 0 auto; object-fit: contain; }
+.bubble .rtitle { font-weight: 600; opacity: 0.88; overflow: hidden; text-overflow: ellipsis; max-width: 110px; }
+.bubble .rproject { font-weight: 500; opacity: 0.82; overflow: hidden; text-overflow: ellipsis; max-width: 110px; }
+.bubble .rsep { opacity: 0.35; }
+.bubble .amsg { font-weight: 500; opacity: 0.85; overflow: hidden; text-overflow: ellipsis; flex-shrink: 1; }
+.bubble .rstate { font-size: 0.85em; opacity: 0.55; }
+.bubble .clock { font-size: 0.85em; opacity: 0.45; font-variant-numeric: tabular-nums; }
+.bubble .xn {
+  font-size: 0.85em; font-weight: 600; opacity: 0.65;
+  padding: 0 6px; border-radius: 999px; background: rgba(255,255,255,0.10);
+}
+
+.bubble .brow.waiting .amsg {
+  color: var(--orange); font-weight: 600;
+  animation: waitflash 1.7s ease-in-out infinite;
+}
+@keyframes waitflash { 0%, 100% { opacity: 1; } 50% { opacity: 0.65; } }
+
+.bubble .amsg.shimmer {
+  background: linear-gradient(100deg,
+    var(--bubble-fg, #F6F0E4) 40%, rgba(255,255,255,0.45) 50%, var(--bubble-fg, #F6F0E4) 60%);
+  background-size: 220% 100%;
+  -webkit-background-clip: text;
+  background-clip: text;
+  color: transparent;
+  animation: shimmer 2.5s linear infinite;
+}
+@keyframes shimmer { from { background-position: 120% 0; } to { background-position: -120% 0; } }
+
+.bubble .sdot {
+  position: relative; width: 8px; height: 8px; border-radius: 50%;
+  flex: 0 0 auto; background: #8A8578;
+}
+.bubble .brow[data-state="working"] .sdot,
+.bubble .brow[data-state="registered"] .sdot { background: var(--amber); }
+.bubble .brow[data-state="waiting"] .sdot { background: var(--orange); }
+.bubble .brow[data-state="done"] .sdot { background: var(--green); }
+.bubble .sdot.plain.spin::after {
+  content: ""; position: absolute; inset: 0; border-radius: 50%;
+  background: inherit;
+  animation: bloom 1.5s ease-out infinite;
+}
+@keyframes bloom { 0% { transform: scale(1); opacity: 0.55; } 100% { transform: scale(2.4); opacity: 0; } }
+
+.bubble .sdot.claude { width: 14px; height: 14px; border-radius: 0; background: transparent !important; }
+.bubble .sdot.claude::after {
+  content: "✻"; font-size: 12px; font-weight: 700; line-height: 14px;
+  display: block; text-align: center;
+}
+.bubble .brow[data-state="working"] .sdot.claude::after,
+.bubble .brow[data-state="registered"] .sdot.claude::after { color: var(--amber); }
