import { describe, expect, it, vi } from "vitest";

type LeaseHost = {
  activate(): Promise<void>;
  deactivate(): Promise<void>;
  reportError(error: unknown): void;
};
type Lease = {
  begin(): void;
  wait(): Promise<void>;
  finish(): Promise<void>;
};
type LeaseModule = {
  PetInteractionLease: new (host: LeaseHost) => Lease;
};

const leaseModulePath = "./pet-interaction-lease";

async function createLease(host: LeaseHost): Promise<Lease> {
  const module = await import(/* @vite-ignore */ leaseModulePath).catch(() => null);
  expect(module).not.toBeNull();
  return new (module as LeaseModule).PetInteractionLease(host);
}

function deferred<T>() {
  let resolve: (value: T) => void;
  const promise = new Promise<T>((r) => { resolve = r; });
  return { promise, resolve: resolve! };
}

describe("pet interaction lease", () => {
  it("does not let a late first release deactivate a newer gesture", async () => {
    const firstActivation = deferred<void>();
    const secondActivation = deferred<void>();
    const host: LeaseHost = {
      activate: vi.fn()
        .mockReturnValueOnce(firstActivation.promise)
        .mockReturnValueOnce(secondActivation.promise),
      deactivate: vi.fn().mockResolvedValue(undefined),
      reportError: vi.fn(),
    };
    const lease = await createLease(host);

    lease.begin();
    expect(host.activate).toHaveBeenCalledTimes(1);
    const firstFinish = lease.finish();
    lease.begin();
    firstActivation.resolve();
    await firstFinish;

    expect(host.deactivate).not.toHaveBeenCalled();

    secondActivation.resolve();
    await lease.finish();
    expect(host.deactivate).toHaveBeenCalledTimes(1);
  });

  it("releases a failed acquisition so the native interaction state cannot remain stale", async () => {
    const failure = new Error("native lease failed");
    const host: LeaseHost = {
      activate: vi.fn().mockRejectedValue(failure),
      deactivate: vi.fn().mockResolvedValue(undefined),
      reportError: vi.fn(),
    };
    const lease = await createLease(host);

    lease.begin();
    await lease.finish();

    expect(host.reportError).toHaveBeenCalledWith(failure);
    expect(host.deactivate).toHaveBeenCalledTimes(1);
  });
});
import { describe, expect, it, vi } from "vitest";

type Point = { x: number; y: number };
type DragOutcome = {
  kind: "click" | "drag" | "cancel";
  completion: Promise<void> | null;
};
type DragController = {
  begin(pointerId: number, point: Point, grabOffset: Point, startedAt: number): boolean;
  move(pointerId: number, point: Point): boolean;
  finish(pointerId: number, point: Point, allowClick: boolean, now: number): DragOutcome | null;
};
type PointerOptions = {
  drag: DragController;
  canBegin(event: PointerEvent): boolean;
  onBegin(): void;
  finishCapture(): Promise<void>;
  onClick(): void;
  now(): number;
  scale(): number;
  reportError(error: unknown): void;
};
type PointerModule = {
  attachPetPointerDrag(element: HTMLElement, options: PointerOptions): void;
};

const pointerModulePath = "./pet-pointer-drag";

async function attach(element: FakeElement, options: PointerOptions): Promise<void> {
  const module = await import(/* @vite-ignore */ pointerModulePath).catch(() => null);
  expect(module).not.toBeNull();
  (module as PointerModule).attachPetPointerDrag(element as unknown as HTMLElement, options);
}

class FakeElement {
  readonly captured = new Set<number>();
  private readonly listeners = new Map<string, (event: PointerEvent) => void>();

  addEventListener(type: string, listener: (event: PointerEvent) => void): void {
    this.listeners.set(type, listener);
  }

  setPointerCapture(pointerId: number): void {
    this.captured.add(pointerId);
  }

  hasPointerCapture(pointerId: number): boolean {
    return this.captured.has(pointerId);
  }

  releasePointerCapture(pointerId: number): void {
    this.captured.delete(pointerId);
  }

  dispatch(type: string, event: PointerEvent): void {
    this.listeners.get(type)?.(event);
  }
}

function pointerEvent(overrides: Partial<PointerEvent> = {}): PointerEvent {
  return {
    pointerId: 1,
    button: 0,
    screenX: 100,
    screenY: 200,
    clientX: 10,
    clientY: 20,
    preventDefault: vi.fn(),
    ...overrides,
  } as PointerEvent;
}

function options(drag: DragController, overrides: Partial<PointerOptions> = {}): PointerOptions {
  return {
    drag,
    canBegin: vi.fn().mockReturnValue(true),
    onBegin: vi.fn(),
    finishCapture: vi.fn().mockResolvedValue(undefined),
