   736	                                Some(r) if r.w > 0.0 => {
   737	                                    let rx = cur.x - wp.x as f64;
   738	                                    let ry = cur.y - wp.y as f64;
   739	                                    rx >= r.x && rx <= r.x + r.w && ry >= r.y && ry <= r.y + r.h
   740	                                }
