   746	                        // lease so an async window move cannot make this overlay
   747	                        // click-through before Pointer Capture receives its end.
   748	                        let ignore = should_ignore_cursor_events(active_drags.contains(label), inside);
   749	                        if apply_ignore_state(&mut last_ignore, label, ignore, |ignore| {
   750	                            win.set_ignore_cursor_events(ignore)
   751	                        }) {
