395	/// Reconciles every persistent desktop-pet instance with a single frontend
396	/// source of truth. Window labels are opaque IDs, never sprite slugs or projects.
397	#[tauri::command]
398	async fn sync_desktop_pet_windows(
399	    app: tauri::AppHandle,
400	    pets: Vec<DesktopPetWindow>,
401	) -> Result<(), String> {
402	    if pets.len() > MAX_DESKTOP_PETS {
403	        return Err(format!("desktop pet limit is {MAX_DESKTOP_PETS}"));
404	    }
405	    let mut ids = std::collections::HashSet::new();
406	    for pet in &pets {
407	        if !valid_pet_id(&pet.id) || !ids.insert(&pet.id) {
408	            return Err("invalid or duplicate desktop pet id".into());
409	        }
410	    }
411	    let generation = app
412	        .try_state::<Mutex<DesktopPetSyncState>>()
413	        .and_then(|state| state.lock().ok().map(|mut state| {
414	            state.generation = state.generation.wrapping_add(1);
415	            state.generation
416	        }))
417	        .ok_or("desktop pet sync state unavailable")?;
418	    std::thread::spawn(move || {
419	        let is_current = app
420	            .try_state::<Mutex<DesktopPetSyncState>>()
421	            .and_then(|state| state.lock().ok().map(|state| state.generation == generation))
422	            .unwrap_or(false);
423	        if is_current {
424	            sync_desktop_pet_windows_impl(app, pets);
425	        }
426	    });
427	    Ok(())
428	}
